package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's deterministic {@code householdId}: the first 12 (upper-case) hex characters of
 * the SHA-256 of {@code normalizedLastName + '|' + postcode}. The id is derived purely from the
 * (lastName, postcode) pair, so every owner with the same lastName and postcode receives the same
 * value automatically, regardless of creation order and without any repository lookup or opt-in.
 *
 * <p>Because the household is now keyed on (lastName, postcode), owners sharing that pair are the
 * same household. This computed id is the single source of truth the household consumers key off:
 * {@link CheckOwnerHouseholdUnique} (the household-duplicate 409 block),
 * {@link DetectOwnerPossibleDuplicate} and {@link DeriveOwnerHouseholdSize}. The request's
 * {@code sharesHousehold} flag no longer creates the link — the link is implicit in the shared id —
 * it only bypasses the duplicate block (see {@link CheckOwnerHouseholdUnique}).
 *
 * <p>Runs after {@link BuildOwner} has created the entity and before {@link CheckOwnerHouseholdUnique}
 * (which sees the resolved {@code householdId}) and {@link SaveOwner} persists it.
 */
public class AssignOwnerHousehold {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(householdId(owner.getLastName(), owner.getPostcode()));
    }

    /**
     * The single source of truth for an owner's household identity: the first 12 upper-case hex
     * characters of the SHA-256 of {@code normalize(lastName) + '|' + postcode}. An absent postcode
     * contributes an empty segment. Two owners share a household exactly when this value is equal.
     */
    static String householdId(String lastName, String postcode) {
        String input = normalize(lastName) + "|" + (postcode == null ? "" : postcode);
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(input.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(12);
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02x", digest[i]));
            }
            return sb.toString().toUpperCase(Locale.ROOT);
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }

    /** Lower-cased, trimmed, with internal whitespace runs collapsed to a single space. */
    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
=== DeriveOwnerHouseholdSize ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Derives the owner's {@code householdSize} at response time: the number of owners sharing this
 * owner's {@link Owner#getHouseholdId() householdId}, counting this owner itself. An owner with no
 * household id is a household of one. The size is exposed as a derived, response-time field on the
 * owner.
 *
 * <p>The current owner is counted explicitly (starting at one) rather than relying on it appearing
 * in {@link OwnerRepository#findAll()}, so the count is correct in the create pipeline — where the
 * owner has been stamped with its household id but not yet persisted — as well as on reads.
 *
 * <p>Wired into both the create pipeline (after {@link AssignOwnerHousehold} has stamped the
 * shared id) and the single-owner GET pipeline. Like {@code bulkSignupWarning} the value is
 * transient and set on the in-flight owner so the responder carries it; it is not persisted.
 */
public class DeriveOwnerHouseholdSize {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String householdId = owner.getHouseholdId();
        if (householdId == null) {
            owner.setHouseholdSize(1);
            return;
        }
        long count = 1; // the owner itself
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
                continue;
            }
            if (householdId.equals(existing.getHouseholdId())) {
                count++;
            }
        }
        owner.setHouseholdSize((int) count);
    }
}
=== CheckOwnerHouseholdUnique ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * The duplicate check for creating an owner: rejects 409 when the new owner would join an existing
 * household — that is, when an existing owner shares the new owner's computed
 * {@link Owner#getHouseholdId() householdId} (owners with the same lastName and postcode are the
 * same household). Because the household is keyed on (lastName, postcode), a second such owner is a
 * household duplicate.
 *
 * <p>The request's {@code sharesHousehold} flag is the sole bypass: when set, the owner is being
 * created as a <em>declared</em> household member, so the block is skipped and the owner is created
 * despite the collision. It no longer creates the household link — the link is implicit in the
 * shared {@code householdId} assigned by {@link AssignOwnerHousehold}.
 *
 * <p>Runs after {@link BuildOwner} and {@link AssignOwnerHousehold} have produced the entity and
 * resolved its {@code householdId}. The new owner is not yet persisted, so
 * {@link OwnerRepository#findAll()} yields only the other owners.
 */
public class CheckOwnerHouseholdUnique {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return; // declared household member: bypass the duplicate block
        }
        String householdId = owner.getHouseholdId();
        if (householdId == null) {
            return;
        }
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
                continue;
            }
            if (existing.isDeleted()) {
                continue; // soft-deleted owners are ignored by the duplicate check
            }
            if (householdId.equals(existing.getHouseholdId())) {
                throw new DuplicateHouseholdException(
                        "An owner in the same household already exists");
            }
        }
    }
}
